use c6_core::{core_stream::ThroughFirstPlayer,core_player::Boundary,map,unit};
use std::io::{Read,Write};
fn main(){
 let mut input=Vec::new();std::io::stdin().read_to_end(&mut input).unwrap();
 let v=ThroughFirstPlayer::decode(&input,map::Limits::default(),unit::Limits::default()).unwrap();
 assert_eq!(v.player_prefix.boundary,Boundary::PlayerHeroes);
 assert_eq!(v.tail,&input[v.consumed..]);assert!(std::ptr::eq(v.tail.as_ptr(),input[v.consumed..].as_ptr()));
 let(encoded,post_items)=v.player_prefix.encode_prefix_with_items(unit::Limits::default()).unwrap();
 assert_eq!(encoded,input[v.core.consumed..v.consumed]);assert_eq!(v.items_used,v.core.items_used+post_items);
 let p=v.player_prefix.first_player.as_ref().unwrap();
 let parts=[p.espionage.encode_with_items(unit::Limits::default()).unwrap(),p.religion.encode_with_items(unit::Limits::default()).unwrap(),p.resources.encode_with_items(unit::Limits::default()).unwrap(),p.stats.encode_with_items(unit::Limits::default()).unwrap(),p.techs.encode_with_items(unit::Limits::default()).unwrap(),p.treasury.encode_with_items(unit::Limits::default()).unwrap(),p.units.encode_with_items(unit::Limits::default()).unwrap(),p.eras.encode_with_items(unit::Limits::default()).unwrap(),p.trade.encode_with_items(unit::Limits::default()).unwrap(),p.great_people_points.encode_with_items(unit::Limits::default()).unwrap(),p.influence.encode_with_items(unit::Limits::default()).unwrap(),p.quests.encode_with_items(unit::Limits::default()).unwrap(),p.wmds.encode_with_items(unit::Limits::default()).unwrap(),p.improvements.encode_with_items(unit::Limits::default()).unwrap(),p.governors.encode_with_items(unit::Limits::default()).unwrap(),p.cultural_identity.encode_with_items(unit::Limits::default()).unwrap()];
 let mut cursors=vec![v.consumed-parts.iter().map(|x|x.0.len()).sum::<usize>()];for(b,_)in &parts{cursors.push(cursors.last().unwrap()+b.len());}
 let shared=map::Limits{max_bytes:v.consumed,max_items:v.items_used,max_allocation:v.core.logical_allocation_used,..map::Limits::default()};
 let player=unit::Limits{max_bytes:encoded.len(),max_items:post_items};
 assert!(ThroughFirstPlayer::decode(&input,shared,player).is_ok());
 for s in[map::Limits{max_bytes:shared.max_bytes-1,..shared},map::Limits{max_items:shared.max_items-1,..shared}]{assert!(ThroughFirstPlayer::decode(&input,s,player).is_err());}
 for l in[unit::Limits{max_bytes:player.max_bytes-1,..player},unit::Limits{max_items:player.max_items-1,..player}]{assert!(ThroughFirstPlayer::decode(&input,shared,l).is_err());}
 for cut in std::iter::once(v.core.consumed).chain(cursors[..cursors.len()-1].iter().copied()).chain(std::iter::once(v.consumed-1)){assert!(ThroughFirstPlayer::decode(&input[..cut],map::Limits::default(),unit::Limits::default()).is_err());}

 let(out,ei)=v.player_prefix.encode_prefix_with_items(player).unwrap();assert_eq!(out,encoded);assert_eq!(ei,post_items);
 for l in[unit::Limits{max_bytes:player.max_bytes-1,..player},unit::Limits{max_items:player.max_items-1,..player}]{assert!(v.player_prefix.encode_prefix_with_items(l).is_err());}
 let mut fields=vec![v.core.consumed,v.consumed,v.items_used,post_items,v.tail.len(),v.player_prefix.unfinished_player_entries as usize,usize::from(p.header.saved_is_alive()),v.core.logical_allocation_used];fields.extend([p.eras.era_hash as usize,p.eras.game_era_hash as usize,p.units.records.capacity as usize,p.units.records.current_id_bits as usize,p.units.records.free_head as usize,p.units.records.free_tail as usize,p.units.records.free_links.len(),p.units.records.entries.len()]);fields.extend([p.wmds.weapons.len(),p.improvements.plot_indices.len(),p.improvements.improvement_array_size as usize,p.governors.capacity as usize,p.governors.entries.len(),p.governors.current_id_bits as usize,p.governors.free_head as usize,p.governors.free_tail as usize,p.governors.free_links.len()]);fields.extend(cursors);
 for(b,i)in &parts{fields.push(b.len());fields.push(*i);}
 println!("{}",fields.iter().map(usize::to_string).collect::<Vec<_>>().join(" "));let mut observations=Vec::new();for e in &p.units.records.entries{observations.extend([i64::from(e.index),i64::from(e.value.id),i64::from(e.value.e_owner)]);}observations.extend(p.units.records.free_links.iter().map(|x|i64::from(*x)));let c=&p.cultural_identity;observations.extend([c.extra_capital_pressure_radius,c.identity_per_turn_for_domestic_trade_route_origin_raw,c.martial_law_modifier,c.post_combat_foreign_loyalty,c.post_combat_local_loyalty,c.additional_golden_age_post_combat_loyalty,c.post_pillage_foreign_loyalty,c.post_pillage_local_loyalty,c.get_skip_free_city_step,c.foreign_identity_per_turn_from_nearby_great_works_raw,c.domestic_identity_per_turn_from_nearby_great_works_raw,c.foreign_identity_per_turn_from_nearby_wonders_raw,c.domestic_identity_per_turn_from_nearby_wonders_raw,c.always_loyal_coastal_home_continent_count].into_iter().map(i64::from));for w in &p.wmds.weapons{observations.extend([i64::from(w.definition_hash),i64::from(w.count)]);}observations.extend(p.improvements.plot_indices.iter().map(|x|i64::from(*x)));for e in &p.governors.entries{let g=&e.governor;observations.extend([i64::from(e.index),i64::from(g.id),i64::from(g.definition_hash),i64::from(g.owning_player),i64::from(g.assigned_city.owner),i64::from(g.assigned_city.component_type),i64::from(g.assigned_city.id)]);}observations.extend(p.governors.free_links.iter().map(|x|i64::from(*x)));println!("{}",observations.iter().map(i64::to_string).collect::<Vec<_>>().join(" "));std::io::stdout().write_all(&encoded).unwrap();
}
